const $=id=>document.getElementById(id),source=[.5,1.5,3,5,7,9],initial=[8,1,6,2,9,4],fmt=x=>Number(x.toFixed(6)).toString();let target=[...initial],match=[0,1,2,3,4,5],evidence;
for(const id of ['target','first','second'])$(id).innerHTML=source.map((_,i)=>'<option value="'+i+'">'+(id==='target'?'Destination ':'Source ')+(i+1)+'</option>').join('');$('second').value='1';
function cost(m){return source.reduce((s,x,i)=>s+(x-target[m[i]])**2/6,0)}
function draw(pair){const c=$('routes'),r=c.getBoundingClientRect(),d=devicePixelRatio||1;c.width=r.width*d;c.height=r.height*d;const g=c.getContext('2d');g.scale(d,d);const px=x=>24+(r.width-48)*x/10;g.fillStyle='#ffffff';g.fillRect(0,0,r.width,r.height);g.font='13px system-ui';g.fillStyle='#596471';g.fillText('Sources',24,24);g.fillText('Destination coordinates',24,315);for(const y of [65,250]){g.strokeStyle='#d4d9df';g.beginPath();g.moveTo(px(0),y);g.lineTo(px(10),y);g.stroke()}for(let i=0;i<=10;i+=2){g.fillStyle='#596471';g.fillText(String(i),px(i)-4,290)}source.forEach((x,i)=>{g.strokeStyle=pair.includes(i)?'#a84269':'#24679b';g.lineWidth=pair.includes(i)?3:1.5;g.beginPath();g.moveTo(px(x),65);g.lineTo(px(target[match[i]]),250);g.stroke();g.fillStyle='#24679b';g.beginPath();g.arc(px(x),65,5,0,2*Math.PI);g.fill();g.fillText(String(i+1),px(x)-4,49)});target.forEach((x,i)=>{g.fillStyle=i===+$('target').value?'#a84269':'#24679b';g.beginPath();g.arc(px(x),250,i===+$('target').value?7:4,0,2*Math.PI);g.fill()})}
function render(){const sorted=target.map((_,i)=>i).sort((i,j)=>target[i]-target[j]),current=cost(match),best=cost(sorted);let inversions=0;for(let i=0;i<6;i++)for(let j=i+1;j<6;j++)if(target[match[i]]>target[match[j]])inversions++;const i=match.findIndex((v,i)=>i<5&&target[v]>target[match[i+1]]),pair=i<0?[]:[i,i+1],saving=i<0?0:2*(source[i+1]-source[i])*(target[match[i]]-target[match[i+1]])/6;
evidence={source:[...source],target:[...target],matching:[...match],optimalMatching:sorted,cost:current,optimalCost:best,wasserstein2:Math.sqrt(best),inversions,nextPair:pair,nextSaving:saving};$('cost').textContent=fmt(current);$('best').textContent=fmt(best);$('inversions').textContent=inversions;$('uncross').disabled=i<0;$('swap').disabled=$('first').value===$('second').value;$('position').value=target[+$('target').value];$('positionValue').textContent=fmt(target[+$('target').value]);$('status').textContent=i<0?'No strict inversion remains. This matching attains the sorted optimum.':'Next uncrossing swaps the destinations of sources '+(i+1)+' and '+(i+2)+'.';$('saving').textContent=i<0?'No positive uncrossing saving remains.':'For the highlighted pair, the exact reduction in mean squared cost is '+fmt(saving)+'.';$('rows').innerHTML=source.map((x,i)=>'<tr><td>'+(i+1)+'</td><td>'+fmt(x)+'</td><td>'+(match[i]+1)+'</td><td>'+fmt(target[match[i]])+'</td><td>'+fmt((x-target[match[i]])**2/6)+'</td></tr>').join('');draw(pair)}
function swap(i,j){[match[i],match[j]]=[match[j],match[i]];render()}
$('uncross').onclick=()=>{if(evidence.nextPair.length)swap(...evidence.nextPair)};$('optimal').onclick=()=>{match=[...evidence.optimalMatching];render()};$('swap').onclick=()=>swap(+$('first').value,+$('second').value);$('position').oninput=()=>{target[+$('target').value]=+$('position').value;render()};['target','first','second'].forEach(id=>$(id).onchange=render);$('reset').onclick=()=>{target=[...initial];match=[0,1,2,3,4,5];$('target').value='0';$('first').value='0';$('second').value='1';render()};$('export').onclick=()=>{const u=URL.createObjectURL(new Blob([JSON.stringify(evidence,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=u;a.download='quantile-matching.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)};window.addEventListener('resize',render);render();
